#[verus_spec]
pub fn try_read(&self) -> Option<RwLockReadGuard<'_, T, G>> {
    proof_decl!{
        let tracked mut read_token: Option<Count<ReadPerm<T>,MAX_READER_U64>> = None;
        let tracked mut retract_read_token: Option<Token<V_MAX_READ_RETRACT_FRACS>> = None;
    }
    proof!{
        use_type_invariant(self);
        lemma_consts_properties();
    }
    let guard = G::read_guard();

    let lock =
        atomic_with_ghost!(
        self.lock => fetch_add(READER);
        update prev -> next;
        ghost g => {
            let prev_usize = prev as usize;
            assume (no_max_reader_overflow(prev_usize));
            // Split a fraction from read_retract_token to track the pending attempt
            retract_read_token = Some(g.read_retract_token.split_one());
            // Check if we successfully acquired the lock
            if prev & (WRITER | MAX_READER | BEING_UPGRADED) == 0 {
                // Successfully acquired - now we need to split a fraction from read_guard_token
                // The read_guard_token should be a Sum::Left at this point based on the invariant
                if g.read_guard_token is Left {
                    let tracked mut count = g.read_guard_token.left();
                    read_token = Some(count.split(1int));
                } else {
                    // This shouldn't happen if the invariant holds
                    admit();
                }
            } else {
                // Failed to acquire - we will undo the fetch_add below
                // The split we did above will be undone when we fetch_sub
            }
        }
    );
    if lock & (WRITER | MAX_READER | BEING_UPGRADED) == 0 {
        Some(
            RwLockReadGuard {
                inner: self,
                guard,
                tracked_token: Tracked(read_token.tracked_unwrap()),
            },
        )
    } else {
        // self.lock.fetch_sub(READER, Release);
        atomic_with_ghost!(
            self.lock => fetch_sub(READER);
            update prev -> next;
            ghost g => {
                // Undo the split we did earlier
                if retract_read_token is Some {
                    let tracked mut token = g.read_retract_token;
                    tracked token.combine(retract_read_token.tracked_unwrap());
                }
                if read_token is Some {
                    let tracked mut count = g.read_guard_token.left();
                    tracked count.combine(read_token.tracked_unwrap());
                }
            }
        );
        None
    }
}

